func newRemittanceProfile() unsafe.Pointer {
	return unsafe.Pointer(new(factoringremittance.RemittanceProfile))
}

func newNRemittanceProfile(n int) unsafe.Pointer {
	return unsafe.Pointer(unsafe.SliceData(make([]factoringremittance.RemittanceProfile, n)))
}

func ptrRemittanceProfile(p unsafe.Pointer, c int32) any {
	r := (*factoringremittance.RemittanceProfile)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 2:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 3:
		return (*string)(unsafe.Pointer(&r.FactoringCompanyID))
	case 4:
		return &r.Mapping
	case 5:
		return &r.HeaderSignature
	case 6:
		return &r.Version
	case 7:
		return &r.CreatedAt
	case 8:
		return &r.UpdatedAt
	}
	return nil
}

func valueRemittanceProfile(p unsafe.Pointer, c int32) any {
	r := (*factoringremittance.RemittanceProfile)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.OrganizationID)
	case 2:
		return string(r.BusinessUnitID)
	case 3:
		return string(r.FactoringCompanyID)
	case 4:
		if r.Mapping == nil {
			return keel.EmptyJSONObject
		}
		return r.Mapping
	case 5:
		return r.HeaderSignature
	case 6:
		return r.Version
	case 7:
		return r.CreatedAt
	case 8:
		return r.UpdatedAt
	}
	return nil
}

func beforeCreateRemittanceProfile(ctx context.Context, p unsafe.Pointer) error {
	return (*factoringremittance.RemittanceProfile)(p).BeforeCreate(ctx)
}

